import { useCallback, useEffect, useState } from "react";
import { AddBookmark } from "../components/AddBookmark";
import { BookmarkList } from "../components/BookmarkList";
import { Bookmark, listBookmarks } from "../services/api";

export function App() {
  const [bookmarks, setBookmarks] = useState<Bookmark[]>([]);
  const [loading, setLoading] = useState(true);
  const [loadError, setLoadError] = useState<string | null>(null);
  const [highlightId, setHighlightId] = useState<number | null>(null);
  const [notice, setNotice] = useState<string | null>(null);

  const refresh = useCallback(async () => {
    setLoading(true);
    setLoadError(null);
    try {
      const data = await listBookmarks("recent");
      setBookmarks(data.items);
    } catch {
      setLoadError("Could not load your bookmarks.");
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    void refresh();
  }, [refresh]);

  function handleSaved(bookmark: Bookmark, duplicate: boolean) {
    setNotice(
      duplicate
        ? "You already saved that link — showing your existing bookmark."
        : "Saved."
    );
    setHighlightId(bookmark.id);
    void refresh();
  }

  return (
    <main className="app">
      <header>
        <h1>Bookmark Manager</h1>
      </header>

      <AddBookmark onSaved={handleSaved} />
      {notice && <p className="notice">{notice}</p>}

      {loading && <p className="muted">Loading…</p>}
      {loadError && <p className="error" role="alert">{loadError}</p>}
      {!loading && !loadError && (
        <BookmarkList bookmarks={bookmarks} highlightId={highlightId} />
      )}
    </main>
  );
}

