:root {
  --bg: #f6f7f9;
  --card: #ffffff;
  --border: #e2e5ea;
  --text: #1c1f24;
  --muted: #6b7280;
  --accent: #2563eb;
  --error: #b91c1c;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  background: var(--bg);
  color: var(--text);
}

.app {
  max-width: 760px;
  margin: 0 auto;
  padding: 2rem 1rem 4rem;
}

header h1 {
  font-size: 1.6rem;
  margin: 0 0 1.25rem;
}

.add-bookmark {
  display: flex;
  gap: 0.5rem;
  flex-wrap: wrap;
}

.add-bookmark input {
  flex: 1 1 320px;
  padding: 0.65rem 0.8rem;
  border: 1px solid var(--border);
  border-radius: 8px;
  font-size: 1rem;
}

.add-bookmark button {
  padding: 0.65rem 1.1rem;
  border: none;
  border-radius: 8px;
  background: var(--accent);
  color: white;
  font-size: 1rem;
  cursor: pointer;
}

.add-bookmark button:disabled {
  opacity: 0.55;
  cursor: default;
}

.notice {
  color: var(--muted);
  font-size: 0.9rem;
  margin: 0.75rem 0 0;
}

.error {
  color: var(--error);
  font-size: 0.9rem;
}

.muted {
  color: var(--muted);
}

.bookmark-list {
  list-style: none;
  padding: 0;
  margin: 1.5rem 0 0;
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}

.bookmark-card {
  display: flex;
  gap: 0.75rem;
  align-items: center;
  background: var(--card);
  border: 1px solid var(--border);
  border-radius: 10px;
  padding: 0.75rem 0.9rem;
}

.bookmark-card.highlighted {
  border-color: var(--accent);
  box-shadow: 0 0 0 2px rgba(37, 99, 235, 0.15);
}

.favicon {
  flex: 0 0 24px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.favicon img {
  border-radius: 4px;
}

.favicon-fallback {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 20px;
  height: 20px;
  border-radius: 4px;
  background: #e5e7eb;
  color: var(--muted);
  font-size: 0.75rem;
  font-weight: 600;
}

.bookmark-body {
  display: flex;
  flex-direction: column;
  min-width: 0;
}

.bookmark-title {
  color: var(--text);
  font-weight: 600;
  text-decoration: none;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.bookmark-title:hover {
  color: var(--accent);
  text-decoration: underline;
}

.bookmark-url {
  color: var(--muted);
  font-size: 0.82rem;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.empty-state {
  margin-top: 3rem;
  text-align: center;
  color: var(--muted);
}

.empty-state h2 {
  color: var(--text);
  margin-bottom: 0.25rem;
}

