def get_bookmark(
    bookmark_id: int,
    session: Session = Depends(get_session),
):
    bookmark = service.get_bookmark(session, bookmark_id)
    if bookmark is None:
        raise HTTPException(
            status_code=404,
            detail={"code": "not_found", "message": "Bookmark not found."},
        )
    return to_out(bookmark)

