/* Toolbar: search + sort */
.toolbar {
  display: flex;
  gap: 0.75rem;
  align-items: center;
  margin-top: 1.25rem;
  flex-wrap: wrap;
}

.search-bar {
  flex: 1 1 260px;
}

.search-bar input {
  width: 100%;
  padding: 0.55rem 0.75rem;
  border: 1px solid var(--border);
  border-radius: 8px;
  font-size: 0.95rem;
}

.sort-control {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  color: var(--muted);
  font-size: 0.9rem;
}

.sort-control select {
  padding: 0.5rem;
  border: 1px solid var(--border);
  border-radius: 8px;
}

.active-filter {
  margin-top: 0.75rem;
  font-size: 0.9rem;
  color: var(--muted);
}

.active-filter button {
  margin-left: 0.5rem;
  background: none;
  border: none;
  color: var(--accent);
  cursor: pointer;
}

/* Card tags + edit */
.card-tags {
  display: flex;
  flex-wrap: wrap;
  gap: 0.3rem;
  margin-top: 0.35rem;
}

.edit-btn {
  flex: 0 0 auto;
  align-self: center;
  background: none;
  border: 1px solid var(--border);
  border-radius: 8px;
  padding: 0.35rem 0.7rem;
  cursor: pointer;
  color: var(--muted);
}

.edit-btn:hover {
  border-color: var(--accent);
  color: var(--accent);
}

/* Tag chips */
.tag-chip {
  display: inline-flex;
  align-items: center;
  gap: 0.25rem;
  background: #eef2ff;
  color: #3730a3;
  border: none;
  border-radius: 999px;
  padding: 0.15rem 0.55rem;
  font-size: 0.78rem;
  cursor: pointer;
}

.tag-chip.small {
  font-size: 0.72rem;
}

.tag-chip button {
  background: none;
  border: none;
  color: inherit;
  cursor: pointer;
  font-size: 0.9rem;
  line-height: 1;
  padding: 0;
}

/* Modal */
.modal-backdrop {
  position: fixed;
  inset: 0;
  background: rgba(17, 24, 39, 0.45);
  display: flex;
  align-items: flex-start;
  justify-content: center;
  padding: 3rem 1rem;
  overflow-y: auto;
}

.modal {
  background: var(--card);
  border-radius: 12px;
  padding: 1.5rem;
  width: 100%;
  max-width: 520px;
  box-shadow: 0 20px 50px rgba(0, 0, 0, 0.2);
}

.modal h2 {
  margin-top: 0;
}

.modal label {
  display: block;
  font-size: 0.85rem;
  color: var(--muted);
  margin-top: 1rem;
}

.modal label input {
  display: block;
  width: 100%;
  margin-top: 0.3rem;
  padding: 0.55rem 0.7rem;
  border: 1px solid var(--border);
  border-radius: 8px;
  font-size: 0.95rem;
}

.modal-actions {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  margin-top: 1.5rem;
}

.modal-actions .spacer {
  flex: 1;
}

.modal-actions button {
  padding: 0.55rem 1rem;
  border-radius: 8px;
  border: 1px solid var(--border);
  background: white;
  cursor: pointer;
  font-size: 0.95rem;
}

.modal-actions .primary {
  background: var(--accent);
  color: white;
  border-color: var(--accent);
}

.modal-actions .danger {
  background: var(--error);
  color: white;
  border-color: var(--error);
}

.modal-actions .danger-text {
  color: var(--error);
  border-color: transparent;
}

.confirm-delete {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  font-size: 0.9rem;
}

/* Note editor */
.note-editor {
  margin-top: 0.3rem;
  border: 1px solid var(--border);
  border-radius: 8px;
  overflow: hidden;
}

.note-toolbar {
  display: flex;
  gap: 0.25rem;
  padding: 0.35rem;
  border-bottom: 1px solid var(--border);
  background: #fafafa;
}

.note-toolbar button {
  border: 1px solid var(--border);
  background: white;
  border-radius: 6px;
  padding: 0.2rem 0.5rem;
  cursor: pointer;
  font-size: 0.85rem;
}

.note-content {
  min-height: 80px;
  padding: 0.6rem 0.7rem;
  font-size: 0.95rem;
  outline: none;
}

.note-content:focus {
  background: #fff;
}

/* Tag input */
.tag-input {
  position: relative;
  margin-top: 0.3rem;
}

.tag-chips {
  display: flex;
  flex-wrap: wrap;
