"""Import/export endpoints (User Stories 5 & 6). See contracts/api.md."""

from fastapi import APIRouter, Depends, File, HTTPException, UploadFile
from fastapi.responses import Response
from sqlmodel import Session

from ..db.engine import get_session
from ..services import bookmarks as bookmarks_service
from ..services import import_service
from ..services.netscape import MalformedImportError, write_netscape_bookmarks

router = APIRouter(prefix="/api", tags=["import-export"])


@router.post("/import")
async def import_bookmarks(
    file: UploadFile = File(...),
    session: Session = Depends(get_session),
) -> dict:
    raw = await file.read()
    try:
        content = raw.decode("utf-8", errors="replace")
    except Exception:
        raise HTTPException(
            status_code=422,
            detail={"code": "invalid_file", "message": "Could not read that file."},
        )

    try:
        summary = import_service.import_bookmarks(session, content)
    except MalformedImportError:
        raise HTTPException(
            status_code=422,
            detail={
                "code": "invalid_file",
                "message": "That doesn't look like a browser bookmarks file. Nothing was imported.",
            },
        )

    return {"added": summary.added, "skipped": summary.skipped}

import { useRef, useState } from "react";
import { ApiError, importBookmarks } from "../services/api";

interface Props {
  onImported: () => void;
}

// Import UI (User Story 5). Export (User Story 6) will be added here later.
export function ImportExport({ onImported }: Props) {
  const inputRef = useRef<HTMLInputElement>(null);
  const [busy, setBusy] = useState(false);
  const [message, setMessage] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);

  async function handleFile(file: File) {
    setError(null);
    setMessage(null);
    setBusy(true);
    try {
      const { added, skipped } = await importBookmarks(file);
      setMessage(
        `Imported ${added} bookmark${added === 1 ? "" : "s"}` +
          (skipped ? `, skipped ${skipped} already saved.` : ".")
      );
      onImported();
    } catch (err) {
      setError(
        err instanceof ApiError ? err.message : "Could not import that file."
      );
    } finally {
      setBusy(false);
      if (inputRef.current) inputRef.current.value = "";
    }
  }

  return (
    <div className="import-export">
      <input
        ref={inputRef}
        type="file"
        accept=".html,text/html"
        hidden
        onChange={(e) => {
          const file = e.target.files?.[0];
          if (file) void handleFile(file);
        }}
      />
      <button type="button" disabled={busy} onClick={() => inputRef.current?.click()}>
        {busy ? "Importing…" : "Import browser bookmarks"}
      </button>
      {message && <span className="import-msg">{message}</span>}
      {error && <span className="error" role="alert">{error}</span>}
    </div>
  );
}

