def _fts_match_expression(query: str) -> str | None:
    """Build a safe FTS5 prefix-match expression from a free-text query.

    Each token is quoted (escaping embedded quotes) and given a trailing ``*`` so partial
    words match; tokens are implicitly AND-ed. Returns None when there is nothing to match.
    """
    tokens = [t for t in query.split() if t.strip()]
    if not tokens:
        return None
    parts = []
    for token in tokens:
        escaped = token.replace('"', '""')
        parts.append(f'"{escaped}"*')
    return " ".join(parts)

